"""The steps themselves. Each takes text and returns text."""


class Step:
    """One transformation."""

    def transform(self, text: str) -> str:
        raise NotImplementedError


class Upper(Step):
    def transform(self, text: str) -> str:
        return text.upper()


class Strip(Step):
    def transform(self, text: str) -> str:
        return text.strip()


class Squeeze(Step):
    def transform(self, text: str) -> str:
        return " ".join(text.split())

