def run_pipeline(text: str, names: list[str]) -> str:
    for name in names:
        text = lookup(name).transform(text)
    return text


def describe(names: list[str]) -> str:
    return " -> ".join(type(lookup(n)).__name__ + ".transform" for n in names)

